import sys
sys.path.insert(0, '.')
from fetcher import fetch

class MockClient:
    def __init__(self):
        self.calls = []
    def get(self, url, timeout=None, **kwargs):
        self.calls.append((url, timeout, kwargs))
        return f'response for {url}'

def test_fetch_passes_timeout():
    client = MockClient()
    result = fetch(client, 'http://example.com')
    url, timeout, kwargs = client.calls[0]
    assert url == 'http://example.com'
    assert timeout == 30
    assert kwargs == {}

def test_fetch_exception_propagation():
    class FailingClient:
        def get(self, url, timeout=None):
            raise RuntimeError('network error')
    client = FailingClient()
    try:
        fetch(client, 'http://example.com')
        assert False, 'expected exception'
    except RuntimeError as e:
        assert str(e) == 'network error'

if __name__ == '__main__':
    test_fetch_passes_timeout()
    test_fetch_exception_propagation()
    print('All tests passed')

